// utils/formValidation.js
export const validateFields = (formData, requiredFields) => {
    const errors = {};
  
    requiredFields.forEach((field) => {
      if (!formData[field]?.trim()) {
        errors[field] = `${field[0].toUpperCase() + field.slice(1)} is required`;
      } else if (field === 'email' && !formData[field].includes('@')) {
        errors.email = 'Please enter a valid email address';
      }
    });
  
    return errors;
  };
  
  export const handleInputChange = (e, formData, setFormData, errors, setErrors) => {
    const { name, value } = e.target;
  
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  
    if (errors[name]) {
      const newErrors = { ...errors };
      delete newErrors[name];
      setErrors(newErrors);
    }
  
    // Optional: clear email error if '@' added
    if (name === 'email' && value.includes('@') && errors.email) {
      const newErrors = { ...errors };
      delete newErrors.email;
      setErrors(newErrors);
    }
  };
